def transform(grid):
    h,w=len(grid),len(grid[0]); out=[r[:] for r in grid]
    seen=set(); objects=[]
    for r in range(h):
        for c in range(w):
            if grid[r][c]==0 or (r,c) in seen: continue
            color=grid[r][c]; stack=[(r,c)]; seen.add((r,c)); cells=[]
            while stack:
                x,y=stack.pop(); cells.append((x,y))
                for a,b in ((x+1,y),(x-1,y),(x,y+1),(x,y-1)):
                    if 0<=a<h and 0<=b<w and (a,b) not in seen and grid[a][b]==color:
                        seen.add((a,b)); stack.append((a,b))
            objects.append((min(x for x,y in cells),min(y for x,y in cells),max(x for x,y in cells),max(y for x,y in cells)))
    objects.sort(); edges=[]
    for i,(r,c,R,C) in enumerate(objects):
        for j in range(i+1,len(objects)):
            s,d,S,D=objects[j]
            if r==s and R==S:
                edges.append((max(d-C-1,c-D-1),i,j,'h'))
            elif c==d and C==D:
                edges.append((max(s-R-1,r-S-1),i,j,'v'))
    p=list(range(len(objects)))
    def find(i):
        while p[i]!=i:
            p[i]=p[p[i]]; i=p[i]
        return i
    for dist,i,j,axis in sorted(edges):
        a,b=find(i),find(j)
        if a==b: continue
        p[a]=b
        r,c,R,C=objects[i]; s,d,S,D=objects[j]
        if axis=='h':
            for x in range(r,R+1):
                for y in range(min(C,D)+1,max(c,d)):
                    if out[x][y]==0: out[x][y]=5
        else:
            for x in range(min(R,S)+1,max(r,s)):
                for y in range(c,C+1):
                    if out[x][y]==0: out[x][y]=5
    return out

